// Shared frontmatter reader for daemon/test/ (test scaffolding, NOT code under test).
//
// WHY THIS EXISTS (pair-programmer #73). `.claude/agents/*.md` and
// `.github/agents/*.agent.md` are generated by the Covenant compiler (`cov build`) from
// `covenant/*.cov`. The generated frontmatter is valid YAML but it is not the shape the
// old per-file readers assumed:
//
//   * some scalars are double-quoted:        color: "blue"      (must equal  color: blue)
//   * `skills:` and `tools:` are block lists: skills:            (must equal  skills: a, b)
//                                               - a
//                                               - b
//   * the first four frontmatter lines are `#` header comments (`# source: X.cov`, ...),
//     and the author's YAML comments are NOT emitted at all: Covenant keeps them as `//`
//     comments in the `.cov` source (packages/import/NORMALIZATIONS.md, List 2 item 5).
//
// The reader is deliberately LINE-ORIENTED rather than a YAML library. A YAML parser
// accepts `max_turns : 5` and `effort=high` is a plain scalar line, which are exactly the
// typos the strict guard in agent-frontmatter.unit.mjs exists to surface; a line reader can
// refuse them. The `yaml` package is used only as an INDEPENDENT ORACLE in
// agent-frontmatter.unit.mjs, which asserts that this reader and a real YAML parser agree
// on every generated agent (so the expected value is never computed by the code under test).
//
// STRICTNESS CONTRACT (no-vacuous-assertions class 5). Nothing is silently dropped. Every
// non-blank, non-comment line lands in exactly one of: a key (`keys`/`data`), a block-list
// item attached to the empty-valued key above it (`lists`), `malformed`, or `indented`.
// Callers that guard a population assert on `malformed` and `indented` too.
//
// LINE ENDINGS. Every entry point normalises CRLF at the read: `core.autocrlf=true` checks
// tracked files out CRLF, and `/^---\n/` and `.split("\n")` strand a `\r` otherwise.

import { readFileSync } from "node:fs";

/** Normalise CRLF (and lone CR from a CRLF split) to LF. */
export function normalizeEol(text) {
  return text.replace(/\r\n/g, "\n");
}

/** Splits `---\n<frontmatter>\n---\n<body>`. `found` is false when there is no
 * well-formed frontmatter block (frontmatter then is ""). */
export function splitFrontmatter(rawContent) {
  const content = normalizeEol(rawContent);
  if (!content.startsWith("---\n")) return { frontmatter: "", body: content, found: false };
  const end = content.indexOf("\n---\n", 4);
  if (end === -1) return { frontmatter: "", body: content, found: false };
  return { frontmatter: content.slice(4, end), body: content.slice(end + 5), found: true };
}

const DOUBLE_QUOTED = /^"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/;
const SINGLE_QUOTED = /^'((?:[^']|'')*)'\s*(?:#.*)?$/;

/** Parses one YAML scalar token (the text after `key:` or after `- `).
 * Returns `{ ok: true, value }` or `{ ok: false, reason }`. Supports plain, "double" and
 * 'single' scalars. Anything else it cannot read faithfully (flow maps, block scalars,
 * unterminated quotes, escapes JSON does not share) is `ok: false` so the caller reports it. */
export function parseScalar(token) {
  const text = token.trim();
  if (text.startsWith('"')) {
    const m = DOUBLE_QUOTED.exec(text);
    if (!m) return { ok: false, reason: "unterminated or trailing text after double-quoted scalar" };
    try {
      return { ok: true, value: JSON.parse(`"${m[1]}"`) };
    } catch {
      return { ok: false, reason: "double-quoted scalar uses an escape this reader does not model" };
    }
  }
  if (text.startsWith("'")) {
    const m = SINGLE_QUOTED.exec(text);
    if (!m) return { ok: false, reason: "unterminated or trailing text after single-quoted scalar" };
    return { ok: true, value: m[1].replace(/''/g, "'") };
  }
  if (text.startsWith("{")) return { ok: false, reason: "flow mapping is not modelled" };
  if (text === "|" || text === ">" || /^[|>][+-]?\d?$/.test(text)) {
    return { ok: false, reason: "block scalar is not modelled" };
  }
  // Plain scalar: ` #` starts a comment (YAML 1.2 §6.6).
  return { ok: true, value: text.replace(/\s+#.*$/, "").trim() };
}

/** Parses a one-line flow sequence `[a, "b"]` via JSON when possible. */
function parseFlowList(token) {
  const text = token.trim();
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed) && parsed.every((x) => typeof x === "string")) return { ok: true, value: parsed };
  } catch {
    /* fall through */
  }
  return { ok: false, reason: "flow sequence is not a JSON list of strings" };
}

/**
 * Parses a frontmatter block (the text between the fences).
 *
 * Returns
 *   data       key -> string  (quotes removed; a block/flow list becomes its members joined
 *              with ", ", i.e. EXACTLY the comma form `skills: a, b`; last duplicate wins)
 *   lists      key -> string[] (members of a block/flow list; absent for scalars)
 *   keys       deduplicated, in-order top-level keys
 *   comments   `#` comment lines with the marker stripped (header lines included)
 *   malformed  raw lines that are not a comment, key line or list item of an open list
 *   indented   raw indented lines that do NOT belong to a block list opened by the key above
 */
export function parseFrontmatter(frontmatter) {
  const data = {};
  const lists = {};
  const keys = [];
  const comments = [];
  const malformed = [];
  const indented = [];
  let openList = null; // key whose value was empty, so `  - item` lines may follow
  let openIndent = null;

  for (const rawLine of normalizeEol(frontmatter).split("\n")) {
    const trimmed = rawLine.trim();
    if (!trimmed) continue;
    if (trimmed.startsWith("#")) {
      comments.push(trimmed.replace(/^#\s?/, ""));
      continue;
    }

    if (/^\s/.test(rawLine)) {
      const item = /^(\s+)-\s+(\S.*)$/.exec(rawLine);
      if (openList !== null && item && (openIndent === null || item[1] === openIndent)) {
        const scalar = parseScalar(item[2]);
        if (scalar.ok) {
          openIndent = item[1];
          lists[openList].push(scalar.value);
          data[openList] = lists[openList].join(", ");
        } else {
          malformed.push(rawLine);
        }
        continue;
      }
      indented.push(rawLine);
      continue;
    }

    const match = rawLine.match(/^([A-Za-z0-9_-]+):(?:\s+(.*))?$/);
    openList = null;
    openIndent = null;
    if (!match) {
      malformed.push(rawLine);
      continue;
    }
    const key = match[1];
    const rawValue = (match[2] ?? "").trim();
    if (!(key in data)) keys.push(key);
    delete lists[key];

    if (rawValue === "" || rawValue.startsWith("#")) {
      data[key] = "";
      lists[key] = [];
      openList = key;
      continue;
    }
    if (rawValue.startsWith("[")) {
      const flow = parseFlowList(rawValue);
      if (flow.ok) {
        lists[key] = flow.value;
        data[key] = flow.value.join(", ");
      } else {
        data[key] = "";
        malformed.push(rawLine);
      }
      continue;
    }
    const scalar = parseScalar(rawValue);
    if (scalar.ok) data[key] = scalar.value;
    else {
      data[key] = "";
      malformed.push(rawLine);
    }
  }

  // A key that never received a list item is a scalar-null, not a list.
  for (const key of Object.keys(lists)) if (lists[key].length === 0) delete lists[key];
  return { data, lists, keys, comments, malformed, indented };
}

/** The members of `key` as an array: the block/flow list when there is one, else the comma
 * form split on commas. [] when the key is absent or empty. */
export function listMembers(parsed, key) {
  if (parsed.lists[key]) return [...parsed.lists[key]];
  const value = parsed.data[key];
  if (typeof value !== "string" || !value.trim()) return [];
  return value.split(",").map((s) => s.trim()).filter(Boolean);
}

/** Reads a generated/hand-written agent file and parses its frontmatter. */
export function readFrontmatterFile(path) {
  const { frontmatter, body, found } = splitFrontmatter(readFileSync(path, "utf8"));
  return { path, frontmatter, body, found, ...parseFrontmatter(frontmatter) };
}

// ─── Covenant generated-file header and `.cov` source comments ─────────────────────────

/** Reads the `# Generated by Covenant ...` header out of parsed `comments`. `source` is the
 * `.cov` basename (`# source: triage.cov`), or undefined when the file is not generated. */
export function generatedHeader(comments) {
  const grab = (re) => {
    for (const c of comments) {
      const m = re.exec(c);
      if (m) return m[1].trim();
    }
    return undefined;
  };
  return {
    generated: comments.some((c) => /^Generated by Covenant\b/.test(c)),
    source: grab(/^source:\s*(\S+\.cov)\s*$/),
    agent: grab(/^agent:\s*(\S+)\s*$/),
    hash: grab(/^hash:\s*(sha256:[0-9a-f]{64})\s*$/),
  };
}

/**
 * Splits a `.cov` source into its contiguous `//` comment blocks. Lines inside a
 * `"""` prompt are skipped (a prompt may legitimately contain `//` at a line start).
 * Each block: { startLine (1-based), lines[], text, nextLine, followingLines[] } where
 * `nextLine` is the first NON-comment line after the block (the item the comment sits above).
 */
export function leadingCommentBlocks(covSource) {
  const lines = normalizeEol(covSource).split("\n");
  const blocks = [];
  let current = null;
  let inPrompt = false;
  const close = (index) => {
    if (!current) return;
    blocks.push({
      ...current,
      text: current.lines.join("\n"),
      nextLine: index < lines.length ? lines[index] : "",
      followingLines: lines.slice(index, index + 4),
    });
    current = null;
  };
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const quotes = (line.match(/"""/g) || []).length;
    if (inPrompt) {
      if (quotes % 2 === 1) inPrompt = false;
      continue;
    }
    const comment = /^\s*\/\/ ?(.*)$/.exec(line);
    if (comment) {
      if (!current) current = { startLine: i + 1, lines: [] };
      current.lines.push(comment[1]);
    } else {
      close(i);
    }
    if (quotes % 2 === 1) inPrompt = true;
  }
  close(lines.length);
  return blocks;
}
